(()=>{
const $=id=>document.getElementById(id),L=LayoutLab,P=LayoutPLC;let rows=[],layout,index,onChange,editor;
const units=Array.from({length:8},(_,i)=>'T'+(i+1)).concat(Array.from({length:8},(_,i)=>'C'+(i+1))),memory=Array.from({length:16},(_,i)=>'M'+(i+1));
function tags(){return [...Object.keys(L.inputs(layout,L.fresh(layout))),...L.outputs(layout),...memory,...units.map(u=>u+'_DONE'),...units.filter(u=>u[0]==='T').map(u=>u+'_TIMING')];}
function changed(next){rows=next;try{localStorage.setItem('plcquest.layout.program.v1.'+index,JSON.stringify(rows));$('programSaved').textContent='Program saved in this browser.';}catch{$('programSaved').textContent='Browser storage unavailable. Keep this tab open to retain your program.';}onChange();}
window.FloorEditor={open(l,i,callback){layout=l;index=i;onChange=callback;rows=[];try{rows=P.validate(JSON.parse(localStorage.getItem('plcquest.layout.program.v1.'+i)||'[]'),l);}catch{}const config={rows,tags:tags(),outputs:[...L.outputs(layout),...memory],onChange:changed};if(editor)editor.setData(config);else editor=new RailEditor($('rungs'),config);$('addRung').hidden=true;$('programSaved').textContent=rows.length?'Saved program restored.':'New floor. Start with an empty program.';$('tagList').textContent=tags().join(' · ');},rows:()=>rows,live(plc){editor?.live(plc.trace);$('plcValues').textContent=Object.entries(plc.timers).map(([k,v])=>`${k}: ${(v.elapsed/1000).toFixed(1)} s`).concat(Object.entries(plc.counters).map(([k,v])=>`${k}: ${v.count} counts`)).join(' · ');}};
})();
